pub fn ctl(args:&[&str],d:&Deadline)->Result<Vec<u8>>{let mut a=vec!["/usr/bin/systemctl".into(),"--system".into()];a.extend(args.iter().map(|s|s.to_string()));io::checked(&a,d)}
pub fn absent(unit:&str,d:&Deadline)->Result<()>{let n=io::native(unit,d)?;ensure!(n["LoadState"]=="not-found"&&n["MainPID"].as_str().is_none_or(|x|x=="0")&&n["ControlPID"].as_str().is_none_or(|x|x=="0")&&n["Job"].as_str().is_none_or(|x|x.is_empty()),"exact role already loaded or executing; preserve original, no retry");Ok(())}
pub fn keeper_source(unit:&str)->String{format!("[Unit]\nDescription=Retain the exact original completed first128 role\nWants={unit}\nAfter={unit}\n")}
pub fn actor_source(argv:&[String],rw:&[String])->Result<String>{ensure!(!argv.is_empty()&&argv.iter().all(|s|!s.contains(['\n','\r','"','\\','%'])&&!s.contains(char::is_whitespace)),"safe exact native ExecStart tokens");ensure!(rw.iter().all(|s|s.starts_with('/')&&!s.contains(char::is_whitespace)),"exact actor writable paths");Ok(format!("[Unit]\nDescription=Original finite first128 metadata transaction\n[Service]\nType=exec\nUser=root\nGroup=root\nRestart=no\nRemainAfterExit=no\nKillMode=control-group\nMemoryAccounting=yes\nMemoryMax=2G\nMemorySwapMax=0\nCPUQuota=100%\nTasksMax=512\nRuntimeMaxSec=300s\nTimeoutStopSec=15s\nUMask=0077\nNoNewPrivileges=yes\nPrivateNetwork=no\nEnvironmentFile=/etc/jetstreamer/horizon-r2.env\nProtectSystem=strict\nProtectHome=read-only\nCapabilityBoundingSet=CAP_DAC_OVERRIDE CAP_SYS_PTRACE\nAmbientCapabilities=CAP_DAC_OVERRIDE CAP_SYS_PTRACE\nAppArmorProfile=horizon-witness-test-deny199-20261107-v1\nReadWritePaths={}\nStandardOutput=journal\nStandardError=journal\nExecStart={}\n",rw.join(" "),argv.join(" ")))}
pub fn install_actor(p:&mut Publisher<'_>,label:&str,unit:&str,argv:&[String],rw:&[String],d:&Deadline)->Result<String>{absent(unit,d)?;let keeper=unit.trim_end_matches(".service").to_owned()+"-retain.target";absent(&keeper,d)?;let b=p.save(label,vec![(unit.into(),actor_source(argv,rw)?.into_bytes()),(keeper.clone(),keeper_source(unit).into_bytes())],d)?;package::install(unit,&io::as_bound(&b[unit])?)?;package::install(&keeper,&io::as_bound(&b[&keeper])?)?;ctl(&["daemon-reload"],d)?;Ok(keeper)}
pub fn install_guard_keeper(p:&mut Publisher<'_>,generation:&str,d:&Deadline)->Result<String>{let keeper=format!("horizon-first163128-first-guard-{generation}-retain.target");absent(&keeper,d)?;let b=p.save("first-guard-keeper",vec![(keeper.clone(),keeper_source(GUARD).into_bytes())],d)?;package::install(&keeper,&io::as_bound(&b[&keeper])?)?;ctl(&["daemon-reload"],d)?;Ok(keeper)}
pub fn original(p:&mut Publisher<'_>,label:&str,unit:&str,keeper:&str,argv:&[String],d:&Deadline)->Result<Value>{let before=io::native(unit,d)?;ensure!(before["MainPID"]=="0"&&before["ControlPID"]=="0"&&before["ActiveState"]=="inactive"&&before["Job"]=="","original role must be dormant");io::unit_command(&before,argv)?;let call=vec!["/usr/bin/systemctl".into(),"--system".into(),"start".into(),keeper.into()];let(code,out,err)=io::command(&call,d)?;let saved=json!({"argv":call,"code":code,"stdout":String::from_utf8_lossy(&out),"stderr":String::from_utf8_lossy(&err)});let path=p.stage.join(format!("{label}-original-outer.json"));io::write(&path,&io::blob(&saved)?,0o600)?;ensure!(code==0,"original role failed; outer preserved");let mut observed=io::native(unit,d)?;
 // The active keeper is intentionally not passed to systemctl --wait: waiting
 // for target inactivity would hang. Wait on the captured original process via
 // pidfd-backed pidwait; fast actors may already have completed successfully.
 if observed["ActiveState"]=="active"&&observed["SubState"]=="running" {
  let original_iid=observed["InvocationID"].clone();let pid=observed["MainPID"].as_str().context("original live PID")?.parse::<u64>()?;ensure!(pid>1,"original live PID absent");
  let pidfile=p.stage.join(format!("{label}-original.pid"));io::write(&pidfile,format!("{pid}\n").as_bytes(),0o600)?;
  let args=vec!["/usr/bin/pidwait".into(),"-F".into(),pidfile.display().to_string()];let(wait_code,wait_out,wait_err)=io::command(&args,d)?;
  observed=io::native(unit,d)?;ensure!(observed["InvocationID"]==original_iid,"original unit identity changed while waiting");
  // pidwait may race original normal exit before pidfd_open; only genuine
  // unchanged terminal manager+PID1 evidence below can resolve that race.
  io::write(&p.stage.join(format!("{label}-original-pidwait.json")),&io::blob(&json!({"argv":args,"code":wait_code,"stdout":String::from_utf8_lossy(&wait_out),"stderr":String::from_utf8_lossy(&wait_err),"bound_iid":original_iid,"pid":pid}))?,0o600)?;
 }
 let n=observed;io::terminal(&n,unit)?;io::unit_command(&n,argv)?;ensure!(n["InvocationID"]!=before["InvocationID"],"no original invocation advancement");let iid=n["InvocationID"].as_str().context("original IID")?;let event=io::success_event(unit,iid,d)?;ensure!(io::native(unit,d)?==n,"original completion identity changed");let keep=io::native(keeper,d)?;ensure!(keep["ActiveState"]=="active"&&keep["SubState"]=="active"&&keep["MainPID"].as_str().is_none_or(|x|x=="0")&&keep["ControlPID"].as_str().is_none_or(|x|x=="0"),"zero-process keeper not retained");Ok(json!({"unit":unit,"invocation_id":iid,"original_native":n,"original_PID1_success_event":event,"original_outer_reaped":true,"original_cgroup_empty":true,"original_descriptors_drained":true,"original_exec_argv":argv,"original_outer":saved,"retention_keeper":keeper,"no_restart_or_deadline_extension":true}))}
pub fn helper_argv(helper:&Bound,route:&str,spec:&Bound)->Result<Vec<String>>{ensure!(matches!(route,"admit-first163128"|"enroll-first163128"|"release-first163128"),"fixed helper route");Ok(vec![helper.path.display().to_string(),route.into(),spec.path.display().to_string(),"--spec-sha256".into(),spec.sha256.clone(),"--self-sha256".into(),helper.sha256.clone()])}
pub fn held_identity(d:&Deadline)->Result<Value>{let n=io::native(PARENT,d)?;ensure!(n["ActiveState"]=="active"&&n["SubState"]=="running"&&n["NRestarts"]=="0"&&n["Restart"]=="no"&&n["ControlPID"]=="0"&&n["Job"]=="","original held parent absent/restarted");let iid=n["InvocationID"].as_str().context("parent IID")?;ensure!(io::hex(iid,32),"parent IID shape");let pid=n["MainPID"].as_str().context("parent PID")?.parse::<u64>()?;ensure!(pid>1,"parent PID");let stat=fs::read_to_string(format!("/proc/{pid}/stat"))?;let ticks=stat.rsplit_once(") ").context("parent stat")?.1.split_whitespace().nth(19).context("parent ticks")?.parse::<u64>()?;let args=parent_argv()?;io::unit_command(&n,&args)?;ensure!(fs::read(format!("/proc/{pid}/cmdline"))?==(args.join("\0")+"\0").as_bytes(),"parent actual argv");use std::os::unix::fs::MetadataExt;let m=fs::metadata(format!("/proc/{pid}/exe"))?;let wanted=fs::metadata(node_program().path)?;ensure!((m.dev(),m.ino())==(wanted.dev(),wanted.ino()),"actual node2 mapped image");let procs=fs::read_to_string(format!("/sys/fs/cgroup/system.slice/{PARENT}/cgroup.procs"))?;ensure!(procs.split_whitespace().collect::<Vec<_>>()==[pid.to_string()],"held parent must have sole process");for rel in ["scratch","output"]{ensure!(fs::read_dir(Path::new(WORK).join(rel))?.next().is_none(),"held parent already uses work");}Ok(json!({"native":n,"iid":iid,"pid":pid,"ticks":ticks}))}
pub fn guard_argv(plan:&Bound)->Vec<String>{let g=guard_program();vec![g.path.display().to_string(),"check".into(),plan.path.display().to_string(),"--plan-sha256".into(),plan.sha256.clone(),"--self-sha256".into(),g.sha256]}
/// Generic private primitive used only by fixed production roles or unique QA
/// roles constructed by native_control. Captures a journal cursor before arm.
pub fn arm_and_wait_timer_for(p:&mut Publisher<'_>,guard:&str,timer:&str,receipt:&str,d:&Deadline)->Result<Value> {
 let old=io::native(guard,d)?["InvocationID"].clone();let cursor_raw=io::query(vec!["/usr/bin/journalctl".into(),"--no-pager".into(),"--output=json".into(),"--lines=1".into()],d)?;let cursor_row:Value=serde_json::from_slice(&cursor_raw)?;let cursor=cursor_row["__CURSOR"].as_str().context("original journal cursor")?;ensure!(!cursor.contains(char::is_whitespace),"journal cursor framing");
 let argv=vec!["/usr/bin/journalctl".into(),"--follow".into(),"--no-pager".into(),"--output=json".into(),"-u".into(),guard.into(),format!("--after-cursor={cursor}")];let mut follower=crate::client::Client::spawn(&argv)?;let mut pending=Vec::new();
 let result=(||->Result<Value>{ctl(&["start",timer],d)?;let mut count=0;loop{let eof=follower.pump(d)?;pending.extend(follower.stdout_chunk());ensure!(pending.len()<=2<<20,"guard pending journal bound");while let Some(index)=pending.iter().position(|b|*b==b'\n'){let row=pending.drain(..=index).collect::<Vec<_>>();if row.len()==1{continue}count+=1;ensure!(count<=256,"guard event count bound");let v:Value=serde_json::from_slice(&row)?;if v["_PID"]=="1"&&v["_UID"]=="0"&&v["UNIT"]==guard&&v["MESSAGE_ID"]=="7ad2d189f7e94e70a38c781354912448"&&v["MESSAGE"]==format!("{guard}: Deactivated successfully.")&&v["INVOCATION_ID"]!=old{let n=io::native(guard,d)?;io::terminal(&n,guard)?;ensure!(n["InvocationID"]==v["INVOCATION_ID"],"timer guard identity changed");let native_timer=io::native(timer,d)?;ensure!(native_timer["ActiveState"]=="active"&&native_timer["SubState"]=="waiting","timer not armed");return Ok(json!({"event":v,"guard_native":n,"timer_native":native_timer}));}}ensure!(!eof,"original journal follower ended before actual timer success");}})();
 let cleanup=follower.stop_and_drain();let event=result?;let(status,stderr)=cleanup?;ensure!(stderr.len()<=65536,"journal stderr bound");io::write(&p.stage.join(receipt),&io::blob(&json!({"schema":"epoch163-first128-original-timer-fire-v1","actual":event,"journal_client_reaped":true,"journal_descriptors_drained":true,"journal_client_status":status,"journal_stderr":String::from_utf8_lossy(&stderr)}))?,0o600)?;Ok(event)
}
pub fn arm_and_wait_timer(p:&mut Publisher<'_>,d:&Deadline)->Result<()>{arm_and_wait_timer_for(p,GUARD,TIMER,"ORIGINAL_FIRST_TIMER_GUARD_EVENT.json",d)?;Ok(())}
